package com.ridego.backend.controller;
import com.ridego.backend.service.AuthService; import jakarta.servlet.http.HttpServletRequest; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.time.temporal.ChronoUnit; import java.util.*; import java.math.BigDecimal;
@RestController @RequestMapping("/api/reservations") public class ReservationController {
 private final JdbcTemplate db; private final AuthService auth; public ReservationController(JdbcTemplate db,AuthService auth){this.db=db;this.auth=auth;}
 private String token(HttpServletRequest r){String h=r.getHeader("Authorization");return h!=null&&h.startsWith("Bearer ")?h.substring(7):null;}
 @GetMapping("/mine") public List<Map<String,Object>> mine(HttpServletRequest req){var u=auth.current(token(req));return db.queryForList("select r.reservation_id as id,r.booking_reference as bookingReference,r.start_date as startDate,r.end_date as endDate,r.number_of_days as numberOfDays,r.total_price as totalPrice,r.currency,r.status,c.brand||' '||c.model as carName,c.slug,l.location_name as pickupLocation from reservations r join cars c on c.car_id=r.car_id join locations l on l.location_id=r.pickup_location_id where r.customer_id=? order by r.created_at desc",((Number)u.get("USER_ID")).longValue());}
 @GetMapping("/{id}") public Map<String,Object> one(@PathVariable long id,HttpServletRequest req){var u=auth.current(token(req));var x=db.queryForList("select r.*,c.brand||' '||c.model as car_name from reservations r join cars c on c.car_id=r.car_id where r.reservation_id=? and r.customer_id=?",id,((Number)u.get("USER_ID")).longValue());if(x.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Reservation not found");return x.get(0);}
 @PostMapping @Transactional public Map<String,Object> create(@RequestBody Map<String,Object>b,HttpServletRequest req){var u=auth.current(token(req));long user=((Number)u.get("USER_ID")).longValue();long carId=num(b,"carId"),pickup=num(b,"pickupLocationId"),ret=num(b,"returnLocationId");LocalDate start=LocalDate.parse(str(b,"startDate")),end=LocalDate.parse(str(b,"endDate"));long days=ChronoUnit.DAYS.between(start,end);if(days<1||start.isBefore(LocalDate.now()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a future pick-up date and a return date after pick-up");
  var car=db.queryForList("select c.car_id,c.daily_rate,c.deposit_amount,c.status,c.location_id from cars c where c.car_id=? and c.is_active=1 for update",carId);if(car.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Vehicle not found");var c=car.get(0);if(!"AVAILABLE".equals(c.get("STATUS").toString()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Vehicle is not currently available");
  int overlap=db.queryForObject("select count(*) from reservations where car_id=? and status in ('CONFIRMED','IN_PROGRESS') and start_date<to_date(?,'YYYY-MM-DD') and end_date>to_date(?,'YYYY-MM-DD')",Integer.class,carId,end.toString(),start.toString());if(overlap>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Vehicle is already reserved for these dates");
  int maintenance=db.queryForObject("select count(*) from maintenance where car_id=? and status in ('SCHEDULED','IN_PROGRESS') and scheduled_start<to_date(?,'YYYY-MM-DD') and scheduled_end>=to_date(?,'YYYY-MM-DD')",Integer.class,carId,end.toString(),start.toString());if(maintenance>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Vehicle is scheduled for maintenance during these dates");
  int overdue=db.queryForObject("select count(*) from rentals rr join reservations oldr on oldr.reservation_id=rr.reservation_id where oldr.car_id=? and rr.status='ACTIVE' and rr.returned_at is null and oldr.end_date<=to_date(?,'YYYY-MM-DD')",Integer.class,carId,start.toString());if(overdue>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Vehicle has an overdue active rental");
  db.queryForObject("select location_id from locations where location_id=? and is_active=1",Long.class,pickup);db.queryForObject("select location_id from locations where location_id=? and is_active=1",Long.class,ret);
  Long insuranceId=b.get("insuranceId")==null?null:Long.valueOf(b.get("insuranceId").toString());String insuranceName=null;BigDecimal insuranceRate=BigDecimal.ZERO;if(insuranceId!=null){var ins=db.queryForMap("select insurance_name,daily_rate from insurance where insurance_id=? and is_active=1",insuranceId);insuranceName=ins.get("INSURANCE_NAME").toString();insuranceRate=(BigDecimal)ins.get("DAILY_RATE");}
  BigDecimal rate=(BigDecimal)c.get("DAILY_RATE"),deposit=(BigDecimal)c.get("DEPOSIT_AMOUNT"),hire=rate.multiply(BigDecimal.valueOf(days)),cover=insuranceRate.multiply(BigDecimal.valueOf(days)),total=hire.add(cover);String ref="RG-"+UUID.randomUUID().toString().replace("-","").substring(0,12).toUpperCase(),key=UUID.randomUUID().toString().replace("-","");
  db.update("insert into reservations(booking_reference,request_key,customer_id,car_id,insurance_id,pickup_location_id,return_location_id,start_date,end_date,number_of_days,daily_rate,insurance_name,insurance_daily_rate,hire_total,insurance_total,total_price,deposit_amount,currency,status,customer_notes) values(?,?,?,?,?,?,?,to_date(?,'YYYY-MM-DD'),to_date(?,'YYYY-MM-DD'),?,?,?,?,?,?,?,?, 'EUR','CONFIRMED',?)",ref,key,user,carId,insuranceId,pickup,ret,start.toString(),end.toString(),days,rate,insuranceName,insuranceRate,hire,cover,total,deposit,b.get("notes"));
  return db.queryForMap("select reservation_id as id,booking_reference as bookingReference,number_of_days as numberOfDays,hire_total as hireTotal,insurance_total as insuranceTotal,total_price as totalPrice,deposit_amount as depositAmount,currency,status from reservations where booking_reference=?",ref);
 }
 @PatchMapping("/{id}/cancel") @Transactional public Map<String,Object> cancel(@PathVariable long id,@RequestBody(required=false) Map<String,Object>b,HttpServletRequest req){var u=auth.current(token(req));long uid=((Number)u.get("USER_ID")).longValue();String reason=b==null||b.get("reason")==null?"Cancelled by customer":b.get("reason").toString();int n=db.update("update reservations set status='CANCELLED',cancelled_at=systimestamp,cancelled_by=?,cancellation_reason=?,updated_at=systimestamp where reservation_id=? and customer_id=? and status='CONFIRMED' and start_date>trunc(sysdate)",uid,reason,id,uid);if(n==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Reservation cannot be cancelled");return Map.of("message","Reservation cancelled");}
 private long num(Map<String,Object>b,String k){return Long.parseLong(str(b,k));}private String str(Map<String,Object>b,String k){Object v=b.get(k);if(v==null||v.toString().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,k+" is required");return v.toString();}
}
